audio = () => {
    switch (audioTrack){

        case 0:

            audioOut = 0;
            break;
        case 1:

            audioOut = (processChannels(audioT) / 3) * musicMasterVolume;
            audioT++;
            break;
        case 2:

            audioOut = (audioT || (a = b = 0, r = .7), c = max(.06 - audioT / 4e4, .03), b += c * ((a += c * (noi(audioT) - a + (r + r / (1 - c)) * (a - b))) - b)) * adsr(0, 0, 1, 2, audioT, audioT) ** 2;
            audioOut = [audioOut * 7 * (1 - ballStereo), audioOut * 7 * ballStereo];
            audioT++;
            break;
        case 3:

            audioOut = (audioT || (a = b = 0, r = .7), c = max(.07 - audioT / 4e4, .04), b += c * ((a += c * (noi(audioT) - a + (r + r / (1 - c)) * (a - b))) - b)) * adsr(0, 0, 1, 2, audioT, audioT) ** 2;
            audioOut = [audioOut * 7 * (1 - ballStereo), audioOut * 7 * ballStereo];
            audioT++;
            break;
    }
},

audio(),

t % 1024 == 0 ? (process()) : audioOut